@push('scripts')<script>
(() => { const rows = document.getElementById('variant-rows'); const add = document.getElementById('add-variant'); let next = {{ count($variantRows) }}; const bind = (button) => button.addEventListener('click', () => { if (rows.children.length > 1) button.closest('.variant-row').remove(); }); rows.querySelectorAll('.remove-variant').forEach(bind); add.addEventListener('click', () => { const row = document.createElement('div'); row.className = 'variant-row'; row.style.cssText = 'display:grid;grid-template-columns:1fr 1fr auto;gap:10px;margin:12px 0'; row.innerHTML = `<div><label>Ukuran EU</label><input class="field" type="number" min="30" max="50" name="sizes[${next}][size]" required></div><div><label>Stok (pasang)</label><input class="field" type="number" min="0" max="10000" name="sizes[${next}][stock]" value="0" required></div><button type="button" class="pill line remove-variant" style="align-self:end;padding:11px">Hapus baris</button>`; rows.appendChild(row); bind(row.querySelector('.remove-variant')); next++; }); })();
</script>@endpush
